import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import "../styles/articles.css";
import CommentsSection from "./CommentsSection";

function ArticlesPage() {
  const { category } = useParams();
  const navigate = useNavigate();
  const token = localStorage.getItem("token");

  const safeCategory = category ? category.toUpperCase() : "ВСІ СТАТТІ";

  const [savedArticles, setSavedArticles] = useState([]);
  const [articles, setArticles] = useState([]);
  const [expandedArticles, setExpandedArticles] = useState({});
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);

  // --- Збережені ---
  useEffect(() => {
    if (!token) return;

    fetch("http://127.0.0.1:8000/api/saved/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => setSavedArticles(data.map((s) => s.article)))
      .catch(console.error);
  }, [token]);

  // --- Користувач + статті ---
  useEffect(() => {
    const loadData = async () => {
      let user = null;

      if (token) {
        const r = await fetch("http://127.0.0.1:8000/api/user/", {
          headers: { Authorization: `Bearer ${token}` },
        });

        if (r.ok) {
          const d = await r.json();

          user = {
            id: Number(d.id),
            isAdmin: d.is_staff || d.is_superuser,
            isPremium: d.is_premium || d.profile?.is_premium || false,
          };

          setCurrentUser(user);
        }
      }

      // --- Якщо є категорія — беремо її ---
      const url = category
        ? `http://127.0.0.1:8000/api/articles/?category=${category}`
        : "http://127.0.0.1:8000/api/articles/";

      const res = await fetch(url, {
        headers: {
          "Content-Type": "application/json",
          ...(token && { Authorization: `Bearer ${token}` }),
        },
      });

      let data = await res.json();

      // --- Преміум фільтр ---
      const privileged =
        user?.isAdmin || user?.isPremium;

      if (!privileged) {
        data = data.filter((a) => !a.is_premium);
      }

      setArticles(data);
      setLoading(false);
    };

    loadData();
  }, [category, token]);

  const toggleComments = (id) => {
    setExpandedArticles((prev) => ({
      ...prev,
      [id]: !prev[id],
    }));
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Видалити статтю?")) return;

    const res = await fetch(`http://127.0.0.1:8000/api/articles/${id}/`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });

    if (res.ok) {
      setArticles((p) => p.filter((a) => a.id !== id));
    }
  };

  if (loading) return <p>Завантаження...</p>;

  return (
    <div className="articles-container">
      <h2>{safeCategory}</h2>

      {articles.length === 0 && <p>Немає статей у цій категорії.</p>}

      <div className="articles-grid">
        {articles.map((a) => (
          <div key={a.id} className="article-card">
            {a.image && <img src={a.image} alt={a.title} className="article-image" />}

            <h3>{a.title}</h3>
            <p>{a.excerpt || a.content?.substring(0, 150) + "..."}</p>

            {currentUser?.isAdmin && (
              <div className="admin-controls">
                <button onClick={() => navigate(`/edit-article/${a.id}`)}>✏️</button>
                <button onClick={() => handleDelete(a.id)}>🗑️</button>
              </div>
            )}

            <button onClick={() => toggleComments(a.id)}>
              💬 {expandedArticles[a.id] ? "Сховати" : "Коментарі"}
            </button>

            {expandedArticles[a.id] && (
              <CommentsSection
                articleId={a.id}
                token={token}
                currentUserId={currentUser?.id}
                isAdmin={currentUser?.isAdmin}
              />
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default ArticlesPage;
